-- 세트 502: 트랜잭션과 락 직접 만들어 보기: 롤백, 락 대기, KILL, 데드락
-- 빈틈 보강 파일럿(docs/specs/spec_pilot_gap_sets.md). 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다.
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (502, 1, 'autocommit 값 확인하기', '`bank` 데이터베이스를 쓰는 서버의 **`autocommit` 설정값**을 `/tmp/ac.txt` 에 저장하세요. (제목 줄 없이 값만)', '`SELECT @@autocommit;` 를 `mariadb -N -e` 로 실행하고 `>` 로 저장합니다. 켜져 있으면 1, 꺼져 있으면 0 으로 나옵니다.', 'mariadb -N -e ''SELECT @@autocommit'' > /tmp/ac.txt
cat /tmp/ac.txt

# 1 = 문장 하나가 끝날 때마다 자동으로 COMMIT. 트랜잭션으로 묶으려면 START TRANSACTION 으로 시작한다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS bank; CREATE DATABASE bank; USE bank; CREATE TABLE accounts (id INT PRIMARY KEY, owner VARCHAR(20), balance INT) ENGINE=InnoDB; INSERT INTO accounts VALUES (1,\\"kim\\",1000),(2,\\"lee\\",500);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ -s /tmp/ac.txt ] ) && ( [ \\"$(cat /tmp/ac.txt)\\" = 1 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일이 있다", "cmd": ["sh", "-c", "[ -s /tmp/ac.txt ]"]}, {"label": "값이 1 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/ac.txt)\\" = 1 ]"]}]', '[{"title": "MariaDB 트랜잭션", "url": "https://mariadb.com/kb/en/transactions/"}, {"title": "InnoDB 락 모드", "url": "https://mariadb.com/kb/en/innodb-lock-modes/"}]'),
  (502, 2, '변경했다가 ROLLBACK 으로 되돌리기', '`kim`(id 1) 계좌의 잔액을 **0 으로 바꾼 뒤 ROLLBACK** 하세요. 한 번의 `mariadb -e` 안에서 `START TRANSACTION; UPDATE ...; SELECT ...; ROLLBACK;` 순서로 실행하고, 바꾼 직후의 값을 `/tmp/during.txt`, 롤백한 뒤 다시 조회한 값을 `/tmp/after.txt` 에 저장하세요.', '변경 직후 값은 트랜잭션 안에서 `SELECT balance ...` 로 읽고 `-N` 으로 값만 저장합니다. 롤백 후 값은 새 `mariadb` 로 다시 조회합니다.', 'mariadb -N bank -e ''START TRANSACTION; UPDATE accounts SET balance=0 WHERE id=1; SELECT balance FROM accounts WHERE id=1; ROLLBACK;'' > /tmp/during.txt
mariadb -N bank -e ''SELECT balance FROM accounts WHERE id=1'' > /tmp/after.txt
cat /tmp/during.txt /tmp/after.txt

# 트랜잭션 안에서는 바뀐 값(0)이 보이지만 ROLLBACK 하면 원래 값(1000)으로 돌아온다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS bank; CREATE DATABASE bank; USE bank; CREATE TABLE accounts (id INT PRIMARY KEY, owner VARCHAR(20), balance INT) ENGINE=InnoDB; INSERT INTO accounts VALUES (1,\\"kim\\",1000),(2,\\"lee\\",500);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(cat /tmp/during.txt)\\" = 0 ] ) && ( [ \\"$(cat /tmp/after.txt)\\" = 1000 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "트랜잭션 안에서는 0 이었다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/during.txt)\\" = 0 ]"]}, {"label": "롤백 후 1000 으로 돌아왔다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/after.txt)\\" = 1000 ]"]}]', '[{"title": "MariaDB 트랜잭션", "url": "https://mariadb.com/kb/en/transactions/"}, {"title": "InnoDB 락 모드", "url": "https://mariadb.com/kb/en/innodb-lock-modes/"}]'),
  (502, 3, '이체를 한 트랜잭션으로 묶어 COMMIT', '`kim` 계좌에서 **300 을 빼고** `lee` 계좌에 **300 을 더하는** 이체를 한 트랜잭션으로 묶어 `COMMIT` 하세요. 끝나면 `kim` 은 700, `lee` 는 800 이어야 합니다.', '`START TRANSACTION; UPDATE ...; UPDATE ...; COMMIT;` 를 한 번의 `mariadb -e` 에 이어 적습니다.', 'mariadb bank -e ''START TRANSACTION; UPDATE accounts SET balance=balance-300 WHERE id=1; UPDATE accounts SET balance=balance+300 WHERE id=2; COMMIT;''
mariadb bank -e ''SELECT * FROM accounts''

# 둘 다 성공해야 의미가 있는 작업은 한 트랜잭션으로 묶는다. 중간에 실패하면 ROLLBACK 으로 둘 다 취소한다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS bank; CREATE DATABASE bank; USE bank; CREATE TABLE accounts (id INT PRIMARY KEY, owner VARCHAR(20), balance INT) ENGINE=InnoDB; INSERT INTO accounts VALUES (1,\\"kim\\",1000),(2,\\"lee\\",500);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(mariadb -N bank -e ''SELECT balance FROM accounts WHERE id=1'')\\" = 700 ] ) && ( [ \\"$(mariadb -N bank -e ''SELECT balance FROM accounts WHERE id=2'')\\" = 800 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "kim 이 700 이다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N bank -e ''SELECT balance FROM accounts WHERE id=1'')\\" = 700 ]"]}, {"label": "lee 가 800 이다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N bank -e ''SELECT balance FROM accounts WHERE id=2'')\\" = 800 ]"]}]', '[{"title": "MariaDB 트랜잭션", "url": "https://mariadb.com/kb/en/transactions/"}, {"title": "InnoDB 락 모드", "url": "https://mariadb.com/kb/en/innodb-lock-modes/"}]'),
  (502, 4, 'SAVEPOINT 까지만 되돌리기', '한 트랜잭션에서 `kim` 의 잔액을 **100 줄이고**(첫 번째 UPDATE), `SAVEPOINT sp1;` 을 만든 뒤 `lee` 의 잔액을 **999 늘렸다가**(두 번째 UPDATE), `ROLLBACK TO sp1;` 로 두 번째 변경만 취소하고 `COMMIT` 하세요. 결과는 `kim` 900, `lee` 500 입니다.', '`SAVEPOINT 이름;` 으로 표시를 남기고 `ROLLBACK TO 이름;` 으로 그 지점까지만 되돌립니다. 그 앞의 변경은 남아 있어 `COMMIT` 으로 확정됩니다.', 'mariadb bank -e ''START TRANSACTION; UPDATE accounts SET balance=balance-100 WHERE id=1; SAVEPOINT sp1; UPDATE accounts SET balance=balance+999 WHERE id=2; ROLLBACK TO sp1; COMMIT;''
mariadb bank -e ''SELECT * FROM accounts''

# ROLLBACK TO 는 트랜잭션을 끝내지 않는다. 마지막에 COMMIT 을 해야 남은 변경이 확정된다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS bank; CREATE DATABASE bank; USE bank; CREATE TABLE accounts (id INT PRIMARY KEY, owner VARCHAR(20), balance INT) ENGINE=InnoDB; INSERT INTO accounts VALUES (1,\\"kim\\",1000),(2,\\"lee\\",500);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(mariadb -N bank -e ''SELECT balance FROM accounts WHERE id=1'')\\" = 900 ] ) && ( [ \\"$(mariadb -N bank -e ''SELECT balance FROM accounts WHERE id=2'')\\" = 500 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "kim 이 900 이다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N bank -e ''SELECT balance FROM accounts WHERE id=1'')\\" = 900 ]"]}, {"label": "lee 는 500 그대로다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N bank -e ''SELECT balance FROM accounts WHERE id=2'')\\" = 500 ]"]}]', '[{"title": "MariaDB 트랜잭션", "url": "https://mariadb.com/kb/en/transactions/"}, {"title": "InnoDB 락 모드", "url": "https://mariadb.com/kb/en/innodb-lock-modes/"}]'),
  (502, 5, '커밋 전 변경은 다른 세션에 안 보인다', '다른 세션이 `kim` 의 잔액을 **999 로 바꿨지만 아직 COMMIT 하지 않은 상태**를 만들어 봅니다. 아래 **첫 번째 세션**을 백그라운드로 띄우고(끝에 `&`), 바로 이어서 **두 번째 세션**에서 `kim` 의 잔액을 읽어 `/tmp/seen.txt` 에 저장하세요.

`mariadb bank -e "START TRANSACTION; UPDATE accounts SET balance=999 WHERE id=1; SELECT SLEEP(20); ROLLBACK;" &`', '첫 세션이 `SLEEP(8)` 로 기다리는 동안(커밋 전) 읽어야 합니다. 읽은 값이 999 가 아니라 원래 값이면 격리가 잘 동작하는 것입니다.', 'mariadb bank -e ''START TRANSACTION; UPDATE accounts SET balance=999 WHERE id=1; SELECT SLEEP(8); ROLLBACK;'' >/dev/null 2>&1 &
sleep 1
mariadb -N bank -e ''SELECT balance FROM accounts WHERE id=1'' > /tmp/seen.txt
cat /tmp/seen.txt
wait

# 커밋 전 변경은 변경한 세션에서만 보인다. 두 번째 세션은 원래 값 1000 을 읽는다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS bank; CREATE DATABASE bank; USE bank; CREATE TABLE accounts (id INT PRIMARY KEY, owner VARCHAR(20), balance INT) ENGINE=InnoDB; INSERT INTO accounts VALUES (1,\\"kim\\",1000),(2,\\"lee\\",500);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(cat /tmp/seen.txt)\\" = 1000 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "읽은 값이 원래 값 1000 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/seen.txt)\\" = 1000 ]"]}]', '[{"title": "MariaDB 트랜잭션", "url": "https://mariadb.com/kb/en/transactions/"}, {"title": "InnoDB 락 모드", "url": "https://mariadb.com/kb/en/innodb-lock-modes/"}]'),
  (502, 6, 'SELECT ... FOR UPDATE 가 만든 락 대기', '한 세션이 `kim`(id 1) 행을 `SELECT ... FOR UPDATE` 로 잠근 상태에서, 다른 세션이 같은 행을 `UPDATE` 하면 기다리다 **시간 초과**가 납니다. 잠금 세션을 백그라운드로 띄우고, 두 번째 세션에서 `SET SESSION innodb_lock_wait_timeout=2;` 후 `UPDATE` 를 실행해 **오류 메시지를 `/tmp/lock.txt`** 에 저장하세요.

`mariadb bank -e "START TRANSACTION; SELECT * FROM accounts WHERE id=1 FOR UPDATE; SELECT SLEEP(20); ROLLBACK;" &`', '오류 메시지는 표준 에러로 나옵니다. `2> /tmp/lock.txt` 로 저장하세요. `ERROR 1205 ... Lock wait timeout exceeded` 가 보여야 합니다.', 'mariadb bank -e ''START TRANSACTION; SELECT * FROM accounts WHERE id=1 FOR UPDATE; SELECT SLEEP(8); ROLLBACK;'' >/dev/null 2>&1 &
sleep 1
mariadb bank -e ''SET SESSION innodb_lock_wait_timeout=2; UPDATE accounts SET balance=1 WHERE id=1;'' 2> /tmp/lock.txt
cat /tmp/lock.txt
wait

# 행을 잡고 있는 세션이 끝나기 전에는 같은 행 변경이 대기한다. 기다림 한도(innodb_lock_wait_timeout)를 넘으면 1205 오류', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS bank; CREATE DATABASE bank; USE bank; CREATE TABLE accounts (id INT PRIMARY KEY, owner VARCHAR(20), balance INT) ENGINE=InnoDB; INSERT INTO accounts VALUES (1,\\"kim\\",1000),(2,\\"lee\\",500);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( grep -q \\"ERROR 1205\\" /tmp/lock.txt ) && ( grep -q \\"Lock wait timeout exceeded\\" /tmp/lock.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "오류 번호 1205 가 있다", "cmd": ["sh", "-c", "grep -q \\"ERROR 1205\\" /tmp/lock.txt"]}, {"label": "Lock wait timeout 메시지가 있다", "cmd": ["sh", "-c", "grep -q \\"Lock wait timeout exceeded\\" /tmp/lock.txt"]}]', '[{"title": "MariaDB 트랜잭션", "url": "https://mariadb.com/kb/en/transactions/"}, {"title": "InnoDB 락 모드", "url": "https://mariadb.com/kb/en/innodb-lock-modes/"}]'),
  (502, 7, '열려 있는 트랜잭션 찾기', '지금 서버에는 누군가 **COMMIT 하지 않고 오래 열어 둔 트랜잭션**이 있습니다. `information_schema.innodb_trx` 에서 **트랜잭션 상태(`trx_state`)와 세션 번호(`trx_mysql_thread_id`)** 두 열을 조회해 `/tmp/trx.txt` 에 저장하세요.', '`SELECT trx_state, trx_mysql_thread_id FROM information_schema.innodb_trx;` 를 `mariadb -e` 로 실행합니다.', 'mariadb -e ''SELECT trx_state, trx_mysql_thread_id FROM information_schema.innodb_trx'' > /tmp/trx.txt
cat /tmp/trx.txt

# innodb_trx 에는 지금 열려 있는 InnoDB 트랜잭션이 한 줄씩 나온다. trx_mysql_thread_id 가 KILL 할 때 쓰는 세션 번호', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS bank; CREATE DATABASE bank; USE bank; CREATE TABLE accounts (id INT PRIMARY KEY, owner VARCHAR(20), balance INT) ENGINE=InnoDB; INSERT INTO accounts VALUES (1,\\"kim\\",1000),(2,\\"lee\\",500);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf; nohup mariadb bank -e ''START TRANSACTION; UPDATE accounts SET balance = balance WHERE id = 1; SELECT SLEEP(600);'' >/dev/null 2>&1 & sleep 1"]', '["sh", "-c", "( grep -q trx_state /tmp/trx.txt ) && ( grep -q RUNNING /tmp/trx.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "제목에 trx_state 가 있다", "cmd": ["sh", "-c", "grep -q trx_state /tmp/trx.txt"]}, {"label": "RUNNING 트랜잭션이 보인다", "cmd": ["sh", "-c", "grep -q RUNNING /tmp/trx.txt"]}]', '[{"title": "MariaDB 트랜잭션", "url": "https://mariadb.com/kb/en/transactions/"}, {"title": "InnoDB 락 모드", "url": "https://mariadb.com/kb/en/innodb-lock-modes/"}]'),
  (502, 8, '오래 열린 세션 KILL 하기', '`innodb_trx` 에 보이는 **오래 열린 트랜잭션의 세션**이 락을 쥐고 있습니다. 세션 번호를 찾아 `KILL` 로 종료해, 열려 있는 트랜잭션이 **0개**가 되게 하세요.', '세션 번호는 `trx_mysql_thread_id` 입니다. `KILL 번호;` 로 종료하면 그 세션의 미커밋 변경은 롤백됩니다.', 'ID=$(mariadb -N -e ''SELECT trx_mysql_thread_id FROM information_schema.innodb_trx LIMIT 1'')
mariadb -e "KILL $ID"
sleep 1
mariadb -N -e ''SELECT COUNT(*) FROM information_schema.innodb_trx''

# KILL 은 세션을 끊고 미커밋 변경을 롤백한다. 운영에서는 무엇을 끊는지 확인하고 실행한다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS bank; CREATE DATABASE bank; USE bank; CREATE TABLE accounts (id INT PRIMARY KEY, owner VARCHAR(20), balance INT) ENGINE=InnoDB; INSERT INTO accounts VALUES (1,\\"kim\\",1000),(2,\\"lee\\",500);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf; nohup mariadb bank -e ''START TRANSACTION; UPDATE accounts SET balance = balance WHERE id = 1; SELECT SLEEP(600);'' >/dev/null 2>&1 & sleep 1"]', '["sh", "-c", "( [ \\"$(mariadb -N -e \\"SELECT COUNT(*) FROM information_schema.innodb_trx\\")\\" = 0 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "열린 트랜잭션이 0개다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N -e \\"SELECT COUNT(*) FROM information_schema.innodb_trx\\")\\" = 0 ]"]}]', '[{"title": "MariaDB 트랜잭션", "url": "https://mariadb.com/kb/en/transactions/"}, {"title": "InnoDB 락 모드", "url": "https://mariadb.com/kb/en/innodb-lock-modes/"}]'),
  (502, 9, '데드락 만들어 보기', '두 세션이 **서로 반대 순서로** 두 행을 갱신하면 데드락이 납니다. 세션 A 는 id 1 → id 2, 세션 B 는 id 2 → id 1 순서로 갱신하게 해서, 각 세션의 오류 출력을 `/tmp/a.txt`, `/tmp/b.txt` 에 저장하세요. (한쪽에는 `Deadlock found` 오류가 나옵니다.)

세션 A: `START TRANSACTION; UPDATE accounts SET balance=balance+1 WHERE id=1; SELECT SLEEP(2); UPDATE accounts SET balance=balance+1 WHERE id=2; COMMIT;`', '두 세션 모두 `&` 로 백그라운드에서 띄우고 `wait` 로 기다립니다. 각 세션을 `2> /tmp/a.txt`, `2> /tmp/b.txt` 로 나눠 저장하세요. 중간 `SELECT SLEEP(2)` 가 서로 첫 행을 쥔 뒤 상대 행을 요구하게 만듭니다. 두 명령을 연달아 한 번에 붙여넣어야 2초 안에 겹칩니다.', 'mariadb bank -e ''START TRANSACTION; UPDATE accounts SET balance=balance+1 WHERE id=1; SELECT SLEEP(2); UPDATE accounts SET balance=balance+1 WHERE id=2; COMMIT;'' >/dev/null 2>/tmp/a.txt &
mariadb bank -e ''START TRANSACTION; UPDATE accounts SET balance=balance+1 WHERE id=2; SELECT SLEEP(2); UPDATE accounts SET balance=balance+1 WHERE id=1; COMMIT;'' >/dev/null 2>/tmp/b.txt &
wait
cat /tmp/a.txt /tmp/b.txt

# 서로 상대가 쥔 행을 기다리면 InnoDB 가 한쪽을 희생자로 골라 롤백한다 (ERROR 1213). 그 세션은 다시 시도한다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS bank; CREATE DATABASE bank; USE bank; CREATE TABLE accounts (id INT PRIMARY KEY, owner VARCHAR(20), balance INT) ENGINE=InnoDB; INSERT INTO accounts VALUES (1,\\"kim\\",1000),(2,\\"lee\\",500);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ -e /tmp/a.txt ] && [ -e /tmp/b.txt ] ) && ( cat /tmp/a.txt /tmp/b.txt | grep -q \\"Deadlock found\\" )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "두 파일이 있다", "cmd": ["sh", "-c", "[ -e /tmp/a.txt ] && [ -e /tmp/b.txt ]"]}, {"label": "한쪽에 Deadlock found 가 있다", "cmd": ["sh", "-c", "cat /tmp/a.txt /tmp/b.txt | grep -q \\"Deadlock found\\""]}]', '[{"title": "MariaDB 트랜잭션", "url": "https://mariadb.com/kb/en/transactions/"}, {"title": "InnoDB 락 모드", "url": "https://mariadb.com/kb/en/innodb-lock-modes/"}]'),
  (502, 10, '데드락을 줄이는 방법', '여러 행을 갱신하는 트랜잭션이 **서로 얽혀 데드락**이 자주 납니다. 가장 효과적인 예방 방법은 무엇인가요?', '데드락은 서로 상대가 쥔 것을 기다리는 고리입니다. 그 고리가 생기지 않게 하려면 락을 잡는 순서를 어떻게 해야 할지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["트랜잭션을 가능한 한 오래 열어 둔다", "모든 트랜잭션이 행을 같은 순서(예: id 오름차순)로 갱신한다", "`innodb_lock_wait_timeout` 을 아주 크게 늘린다", "autocommit 을 끄고 COMMIT 을 미룬다"]', 1, '데드락은 서로 반대 순서로 락을 잡을 때 생깁니다. 모두 같은 순서로 접근하면 서로를 기다리는 고리가 생기지 않습니다. 트랜잭션을 길게 열거나 COMMIT 을 미루면 락을 오래 쥐어 오히려 나빠지고, 대기 시간을 늘리는 것은 데드락과 무관합니다.', NULL, NULL, NULL, NULL),
  (502, 11, '행을 잠그며 읽기', '이체 전에 `kim`(id 1) 행을 **다른 세션이 못 바꾸게 잠그며 읽는** 문장입니다. 빈칸을 채우세요.', '행 락을 거는 읽기 구문입니다.', NULL, NULL, '[]', 'fill', '["FOR UPDATE", "WITH LOCK", "HOLD ROW", "LOCK ROW"]', NULL, '`SELECT ... FOR UPDATE` 는 읽은 행에 쓰기 락을 걸어, 트랜잭션이 끝날 때까지 다른 세션이 그 행을 바꾸지 못하게 합니다. 나머지는 MariaDB 구문이 아닙니다.', '[0]', 'SELECT * FROM accounts WHERE id = 1 {0};', NULL, NULL),
  (502, 12, 'SAVEPOINT 를 쓰는 트랜잭션 순서', '아래 카드를 SAVEPOINT 로 **일부만 되돌리고 확정하는** 트랜잭션의 실행 순서로 놓으세요.', '트랜잭션을 연 뒤 변경하고, 되돌릴 지점을 표시합니다. 그 이후 변경만 취소하고 마지막에 확정하는 흐름을 떠올려 보세요.', NULL, NULL, '[]', 'order', '["ROLLBACK TO sp1", "START TRANSACTION", "COMMIT", "두 번째 UPDATE", "SAVEPOINT sp1", "첫 번째 UPDATE"]', NULL, '트랜잭션을 시작하고 첫 변경을 한 뒤 SAVEPOINT 로 지점을 표시합니다. 두 번째 변경 후 ROLLBACK TO sp1 으로 표시한 지점까지만 되돌리고, 마지막에 COMMIT 으로 남은 변경(첫 번째 UPDATE)을 확정합니다.', '[1, 5, 4, 3, 0, 2]', NULL, NULL, NULL);
